import type { RequestHandler } from './$types';

import { unauthenticated } from '#lib/server/auth';
import type { IssueCategoryList } from '#lib/types/issue-category';
import { db } from '../../../prisma/db';

export const GET: RequestHandler = async ({ locals }) => {
  const employee = locals.employee;
  if (!employee) return unauthenticated();

  const rows = await db.orm.public.IssueCategory
    .select('categoryId', 'categoryName', 'defaultPriority')
    .all();

  const items = rows
    .map((row) => ({
      category_id: Number(row.categoryId),
      category_name: row.categoryName,
      default_priority: row.defaultPriority,
    }))
    .sort((a, b) => a.category_id - b.category_id);

  return Response.json({ total: items.length, items } satisfies IssueCategoryList);
};
